\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Lancet-inspired Color Theme (deep navy + clinical teal + muted gold) ──
\definecolor{primary}{HTML}{0F2B4C}
\definecolor{secondary}{HTML}{1A6B6A}
\definecolor{accent}{HTML}{B8860B}
\definecolor{bgposter}{HTML}{F1F4F8}
\definecolor{redbg}{HTML}{F0F7F7}
\definecolor{bluebg}{HTML}{EEF2F8}
\definecolor{darkbg}{HTML}{F4F0EB}
\definecolor{redtitlebg}{HTML}{E0EEEE}
\definecolor{bluetitlebg}{HTML}{DDE5F0}
\definecolor{darktitlebg}{HTML}{E8E2DA}
\definecolor{textdark}{HTML}{1A1A2E}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E8F4F4}
\definecolor{warningbg}{HTML}{FFF3E0}
\definecolor{warningedge}{HTML}{E65100}
\definecolor{successbg}{HTML}{E8F5E9}
\definecolor{successedge}{HTML}{2E7D32}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
  warningcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warningbg,
    borderline west={6pt}{0pt}{warningedge},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{warningedge},
    coltitle=warningedge, colbacktitle=warningbg!80!white,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={warningedge!40},
    valign=top, drop shadow={opacity=0.15},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════════
% TITLE BAR (rows 1-3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries Artificial Intelligence in Clinical Decision-Making:}\\[8pt]
  {\fontsize{72}{86}\selectfont\bfseries Performance, Safety, and Implementation Gaps}\\[18pt]
  {\fontsize{36}{44}\selectfont The Lancet Digital Health \,|\, AI in Clinical Medicine Symposium \,|\, Systematic Review of 400+ Studies}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{white!70} Based on evidence published in \textit{The Lancet Digital Health} (2023)}
}

% ══════════════════════════════════════════════════════════════
% STAT BANNER (rows 4-6) — anchor stat + key comparisons
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{warningedge!60}{warningbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{80}{96}\selectfont\bfseries\color{warningedge} {$<$}5\%}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} of published AI models reach}\\[2pt]
      {\fontsize{28}{34}\selectfont\color{textdark}\bfseries prospective clinical validation}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{secondary} 87.5\%}\\[-2pt]
      {\fontsize{30}{36}\selectfont\color{textgray} vs}\\[-2pt]
      {\fontsize{62}{76}\selectfont\bfseries\color{textgray} 78.2\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} AI vs.\ clinician-only sensitivity}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{warningedge!50}{warningbg!70!white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{warningedge} 18\%}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} of studies report any}\\[2pt]
      {\fontsize{28}{34}\selectfont\color{textdark}\bfseries demographic bias assessment}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════
% ROW A: rows 6–11
% ══════════════════════════════════════════════════════════════

% ── Col 1: Background & Motivation ──
\posterbox[redcard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item AI-based clinical decision support systems (CDSS) are rapidly expanding across diagnostic, prognostic, and therapeutic domains
    \item Systematic review of \textbf{400+ studies} evaluating AI in clinical workflows
    \item Growing gap between controlled research performance and bedside deployment
  \end{itemize}
  \vspace{10pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\centering\vspace{6pt}
    {\fontsize{34}{42}\selectfont\bfseries\color{primary} Central Question:}\\[4pt]
    {\fontsize{32}{40}\selectfont Why do so few validated AI models reach clinical practice?}
  \vspace{6pt}}}
}

% ── Col 2: Diagnostic Performance ──
\posterbox[bluecard, title={Diagnostic Performance}
]{name=diagperf, column=2, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \renewcommand{\arraystretch}{1.5}
  \centering
  {\fontsize{30}{38}\selectfont
  \begin{tabular}{l c c c c}
    \rowcolor{primary!15}
    \textbf{Domain} & \textbf{AI Sens.} & \textbf{Clin. Sens.} & \textbf{AI Spec.} & \textbf{Clin. Spec.} \\
    Radiology & 89.3\% & 79.8\% & 94.0\% & 92.1\% \\
    \rowcolor{primary!8}
    Dermatology & 86.7\% & 76.5\% & 91.8\% & 89.4\% \\
    Ophthalmology & 90.1\% & 82.3\% & 95.2\% & 93.7\% \\
    \rowcolor{primary!8}
    Pathology & 84.0\% & 74.1\% & 91.5\% & 90.0\% \\
  \end{tabular}}
  \vspace{12pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\centering\vspace{6pt}
    {\fontsize{34}{42}\selectfont\bfseries\color{secondary} +9.3 percentage points}\\[3pt]
    {\fontsize{30}{38}\selectfont median sensitivity advantage for AI}
  \vspace{6pt}}}
  \vspace{8pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\centering\vspace{6pt}
    {\fontsize{34}{42}\selectfont\bfseries\color{accent} 32\% faster}\\[3pt]
    {\fontsize{30}{38}\selectfont diagnostic turnaround time with AI}
  \vspace{6pt}}}
}

% ── Col 3: The Implementation Gap (ANCHOR) ──
\posterbox[warningcard, title={The Implementation Gap}
]{name=implgap, column=3, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \vspace{2pt}
  \colorbox{warningedge!18}{\parbox{0.94\linewidth}{\centering\vspace{8pt}
    {\fontsize{62}{74}\selectfont\bfseries\color{warningedge} 692}\\[4pt]
    {\fontsize{30}{38}\selectfont FDA-cleared AI/ML medical devices (2023)}
  \vspace{8pt}}}
  \vspace{8pt}

  {\fontsize{32}{42}\selectfont\bfseries Key Barriers to Translation:}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Data infrastructure} $\to$ fragmented EHR systems, poor interoperability
    \item \textbf{Regulatory uncertainty} $\to$ frameworks lag AI development pace
    \item \textbf{Clinician trust} $\to$ insufficient model explainability
    \item \textbf{Economic evidence} $\to$ limited cost-effectiveness analyses
    \item \textbf{Workflow integration} $\to$ poor fit with clinical processes
  \end{itemize}
}

% ══════════════════════════════════════════════════════════════
% ROW B: rows 11–16
% ══════════════════════════════════════════════════════════════

% ── Col 1: Safety & Bias ──
\posterbox[warningcard, title={Safety, Bias \& Health Equity}
]{name=safety, column=1, between=row11 and row16}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \colorbox{warningedge!18}{\parbox{0.94\linewidth}{\centering\vspace{8pt}
    {\fontsize{52}{64}\selectfont\bfseries\color{warningedge} Only 18\%}\\[4pt]
    {\fontsize{30}{38}\selectfont of studies assessed algorithmic bias}\\[2pt]
    {\fontsize{30}{38}\selectfont across demographic groups}
  \vspace{8pt}}}
  \vspace{10pt}

  \begin{itemize}[itemsep=10pt]
    \item \textbf{5--12 pp sensitivity gaps} for underrepresented populations
    \item Dermatology AI trained predominantly on lighter skin tones shows largest disparities
    \item Adverse events in ${<}$1\% of prospective trials, but under-reporting suspected
  \end{itemize}
  \vspace{8pt}

  \colorbox{warningedge!12}{\parbox{0.94\linewidth}{\vspace{6pt}\centering
    {\fontsize{30}{38}\selectfont\color{warningedge}\bfseries No standardised safety-reporting}\\[2pt]
    {\fontsize{30}{38}\selectfont\color{warningedge}\bfseries framework exists for AI-CDSS}
  \vspace{6pt}}}
}

% ── Col 2: Key Findings Summary ──
\posterbox[darkcard, title={Key Findings}
]{name=findings, column=2, between=row11 and row16}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\vspace{6pt}
    {\fontsize{32}{40}\selectfont\color{secondary}\bfseries $\blacktriangleright$ Diagnostic Accuracy}\\[4pt]
    {\fontsize{32}{40}\selectfont AI: \textbf{87.5\%} sensitivity, \textbf{93.1\%} specificity}\\[2pt]
    {\fontsize{32}{40}\selectfont Clinicians: \textbf{78.2\%} sensitivity, \textbf{91.4\%} specificity}
  \vspace{6pt}}}
  \vspace{8pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\vspace{6pt}
    {\fontsize{32}{40}\selectfont\color{accent}\bfseries $\blacktriangleright$ Imaging Domains Lead}\\[4pt]
    {\fontsize{32}{40}\selectfont Radiology, dermatology, ophthalmology show largest gains via deep learning}
  \vspace{6pt}}}
  \vspace{8pt}

  \colorbox{warningedge!15}{\parbox{0.94\linewidth}{\vspace{6pt}
    {\fontsize{32}{40}\selectfont\color{warningedge}\bfseries $\blacktriangleright$ Equity Gap}\\[4pt]
    {\fontsize{32}{40}\selectfont 82\% of studies lack any demographic bias audit}
  \vspace{6pt}}}
  \vspace{8pt}

  \colorbox{primary!18}{\parbox{0.94\linewidth}{\vspace{6pt}
    {\fontsize{32}{40}\selectfont\color{primary}\bfseries $\blacktriangleright$ Translation Bottleneck}\\[4pt]
    {\fontsize{32}{40}\selectfont $<$5\% of published models validated prospectively in real-world settings}
  \vspace{6pt}}}
}

% ── Col 3: Sensitivity Comparison Visual ──
\posterbox[bluecard, title={AI vs.\ Clinician Sensitivity by Domain}
]{name=senscomp, column=3, between=row11 and row16}{
  \fontsize{34}{44}\selectfont
  \vspace{6pt}

  % Radiology
  {\fontsize{32}{40}\selectfont\bfseries Radiology}\\[4pt]
  \colorbox{secondary!25}{\parbox{0.82\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\bfseries\color{white} AI: 89.3\%}\vspace{3pt}}}\\[2pt]
  \colorbox{primary!15}{\parbox{0.72\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\color{textgray} Clin: 79.8\%}\vspace{3pt}}}\\[10pt]

  % Dermatology
  {\fontsize{32}{40}\selectfont\bfseries Dermatology}\\[4pt]
  \colorbox{secondary!25}{\parbox{0.79\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\bfseries\color{white} AI: 86.7\%}\vspace{3pt}}}\\[2pt]
  \colorbox{primary!15}{\parbox{0.68\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\color{textgray} Clin: 76.5\%}\vspace{3pt}}}\\[10pt]

  % Ophthalmology
  {\fontsize{32}{40}\selectfont\bfseries Ophthalmology}\\[4pt]
  \colorbox{secondary!25}{\parbox{0.84\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\bfseries\color{white} AI: 90.1\%}\vspace{3pt}}}\\[2pt]
  \colorbox{primary!15}{\parbox{0.76\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\color{textgray} Clin: 82.3\%}\vspace{3pt}}}\\[10pt]

  % Pathology
  {\fontsize{32}{40}\selectfont\bfseries Pathology}\\[4pt]
  \colorbox{secondary!25}{\parbox{0.77\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\bfseries\color{white} AI: 84.0\%}\vspace{3pt}}}\\[2pt]
  \colorbox{primary!15}{\parbox{0.66\linewidth}{\vspace{3pt}\hfill{\fontsize{32}{38}\selectfont\color{textgray} Clin: 74.1\%}\vspace{3pt}}}
  \vspace{6pt}

  \centering
  {\fontsize{28}{34}\selectfont\color{textgray}\textit{Bar widths proportional to sensitivity values}}
}

% ══════════════════════════════════════════════════════════════
% ROW C: rows 16–20
% ══════════════════════════════════════════════════════════════

% ── Col 1: Study Scope ──
\posterbox[redcard, title={Study Scope \& Methods}
]{name=scope, column=1, between=row16 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  \begin{itemize}[itemsep=10pt]
    \item Systematic review: \textbf{400+ studies}
    \item Domains: radiology, dermatology, ophthalmology, pathology
    \item Metrics: sensitivity, specificity, turnaround time, bias reporting
    \item Source: \textit{The Lancet Digital Health} (2023)
  \end{itemize}
  \vspace{10pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{\vspace{6pt}\centering
    {\fontsize{30}{38}\selectfont\color{primary} Covers diagnostic, prognostic,}\\[2pt]
    {\fontsize{30}{38}\selectfont\color{primary} and therapeutic AI-CDSS applications}
  \vspace{6pt}}}
}

% ── Col 2: Recommendations ──
\posterbox[darkcard, title={Recommendations}
]{name=recs, column=2, between=row16 and row20}{
  \fontsize{33}{43}\selectfont
  \vspace{4pt}
  \begin{enumerate}[itemsep=8pt]
    \item \textbf{Mandate prospective validation} including multi-site, diverse-population trials
    \item \textbf{Standardise bias auditing} via demographic-stratified reporting requirements
    \item \textbf{Develop safety registries} analogous to pharmacovigilance systems
    \item \textbf{Invest in interoperability} through open standards (FHIR, OMOP)
    \item \textbf{Prioritise explainability} to build clinician and patient trust
  \end{enumerate}
}

% ── Col 3: Key Takeaways ──
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row16 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}

  \colorbox{white!90!primary}{\parbox{0.94\linewidth}{\vspace{8pt}
    {\fontsize{34}{42}\selectfont\color{primary}\bfseries 1.}\hspace{4pt}
    {\fontsize{34}{42}\selectfont AI demonstrates \textbf{meaningful diagnostic gains} over standard clinical workflows across imaging domains}
  \vspace{8pt}}}
  \vspace{6pt}

  \colorbox{white!90!primary}{\parbox{0.94\linewidth}{\vspace{8pt}
    {\fontsize{34}{42}\selectfont\color{warningedge}\bfseries 2.}\hspace{4pt}
    {\fontsize{34}{42}\selectfont The \textbf{$<$5\% prospective validation rate} reveals a critical implementation gap between research and practice}
  \vspace{8pt}}}
  \vspace{6pt}

  \colorbox{white!90!primary}{\parbox{0.94\linewidth}{\vspace{8pt}
    {\fontsize{34}{42}\selectfont\color{warningedge}\bfseries 3.}\hspace{4pt}
    {\fontsize{34}{42}\selectfont \textbf{Bias assessment remains rare} — coordinated action across research, regulatory, and delivery ecosystems is essential}
  \vspace{8pt}}}
}

\end{tcbposter}
\end{document}

