t}%\n      {\\fontsize{62}{76}\\selectfont\\bfseries\\color{secondary} 87.5\\%}\\\\[-2pt]\n      {\\fontsize{30}{36}\\selectfont\\color{textgray} vs}\\\\[-2pt]\n      {\\fontsize{62}{76}\\selectfont\\bfseries\\color{textgray} 78.2\\%}\\\\[4pt]\n      {\\fontsize{26}{32}\\selectfont\\color{textdark} AI vs.\\ clinician-only sensitivity}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.31\\linewidth}\\centering\n    \\fcolorbox{warningedge!50}{warningbg!70!white}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{72}{86}\\selectfont\\bfseries\\color{warningedge} 18\\%}\\\\[6pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} of studies report any}\\\\[2pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark}\\bfseries demographic bias assessment}\\vspace{8pt}%\n    }}\n  \\end{minipage}\n}\n\n% ══════════════════════════════════════════════════════════════\n% ROW A: rows 6–11\n% ══════════════════════════════════════════════════════════════\n\n% ── Col 1: Background & Motivation ──\n\\posterbox[redcard, title={Background \\& Motivation}\n]{name=background, column=1, between=row6 and row11}{\n  \\fontsize{34}{44}\\selectfont\n  \\begin{itemize}[itemsep=10pt]\n    \\item AI-based clinical decision support systems (CDSS) are rapidly expanding across diagnostic, prognostic, and therapeutic domains\n    \\item Systematic review of \\textbf{400+ studies} evaluating AI in clinical workflows\n    \\item Growing gap between controlled research performance and bedside deployment\n  \\end{itemize}\n  \\vspace{10pt}\n  \\colorbox{secondary!20}{\\parbox{0.94\\linewidth}{\\centering\\vspace{6pt}\n    {\\fontsize{34}{42}\\selectfont\\bfseries\\color{primary} Central Question:}\\\\[4pt]\n    {\\fontsize{32}{40}\\selectfont Why do so few validated AI models reach clinical practice?}\n  \\vspace{6pt}}}\n}\n\n% ── Col 2: Diagnostic Performance ──\n\\posterbox[bluecard, title={Diagnostic Performance}\n]{name=diagperf, column